// 1. Install dependencies:
//    npm install lighthouse chrome-launcher

const lighthouse = require('lighthouse');
const chromeLauncher = require('chrome-launcher');

(async () => {
  // 2. Launch a headless Chrome instance.
  const chrome = await chromeLauncher.launch({chromeFlags: ['--headless']});

  // 3. Run Lighthouse, targeting only the preconnect audit.
  const options = {
    port: chrome.port,
    onlyAudits: ['uses-rel-preconnect'],
    disableStorageReset: true,
  };
  const runnerResult = await lighthouse('https://qwww.americanexpress.com', options);

  // 4. Extract and print the suggested origins.
  const preconnectAudit = runnerResult.lhr.audits['uses-rel-preconnect'];
  console.log('Score:', preconnectAudit.score);
  console.log('Suggested origins and wasted ms:');
  preconnectAudit.details.items.forEach(item => {
    console.log(`  • ${item.url}  —  ${item.wastedMs} ms`);
  });

  // 5. Clean up.
  await chrome.kill();
})();
